class Solution {
  private static int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  public long maxGCDScore(int[] nums, int k) {
    int n = nums.length;
    int[] tz = new int[n];
    for (int i = 0; i < n; i++) tz[i] = Integer.numberOfTrailingZeros(nums[i]);
    long best = 0;
    for (int l = 0; l < n; l++) {
      int g = 0, minTz = Integer.MAX_VALUE, cnt = 0;
      for (int r = l; r < n; r++) {
        g = gcd(g, nums[r]);
        if (tz[r] < minTz) {
          minTz = tz[r];
          cnt = 1;
        } else if (tz[r] == minTz) cnt++;
        long score = (long) (r - l + 1) * g * (cnt <= k ? 2 : 1);
        if (score > best) best = score;
      }
    }
    return best;
  }
}
